class Solution:
    def countNoZeroPairs(self, n: int) -> int:
        def ok(x):
            while x > 0:
                if x % 10 == 0:
                    return False
                x //= 10
            return True
        return sum(1 for a in range(1, n) if ok(a) and ok(n - a))

