class Solution {
public:
    long long countNoZeroPairs(long long n) {
        auto ok = [](long long x) {
            while (x > 0) {
                if (x % 10 == 0) return false;
                x /= 10;
            }
            return true;
        };
        long long ans = 0;
        for (long long a = 1; a < n; a++)
            if (ok(a) && ok(n - a)) ans++;
        return ans;
    }
};

