class Solution:
    def countNoZeroPairs(self, n: int) -> int:
        digits = []
        m = n
        while m > 0:
            digits.append(m % 10)
            m //= 10
        L = len(digits)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, c, sa, sb):
            if i == L:
                return 1 if (c == 0 and sa and sb) else 0
            d = digits[i]
            res = 0
            for x in range(10):
                if x == 0 and sa:
                    continue
                for y in range(10):
                    if y == 0 and sb:
                        continue
                    if (x + y + c) % 10 != d:
                        continue
                    res += dp(i + 1, (x + y + c) // 10, sa or x > 0, sb or y > 0)
            return res

        return dp(0, 0, False, False)

