class Solution {
public:
    long long countNoZeroPairs(long long n) {
        vector<int> dg;
        long long m = n;
        while (m > 0) { dg.push_back(m % 10); m /= 10; }
        int L = dg.size();
        static long long memo[20][2][2][2];
        memset(memo, -1, sizeof(memo));
        function<long long(int,int,bool,bool)> dp = [&](int i, int c, bool sa, bool sb) -> long long {
            if (i == L) return (c == 0 && sa && sb) ? 1 : 0;
            long long &res = memo[i][c][sa][sb];
            if (res != -1) return res;
            res = 0;
            int d = dg[i];
            for (int x = 0; x < 10; x++) {
                if (x == 0 && sa) continue;
                for (int y = 0; y < 10; y++) {
                    if (y == 0 && sb) continue;
                    if ((x + y + c) % 10 != d) continue;
                    res += dp(i + 1, (x + y + c) / 10, sa || x > 0, sb || y > 0);
                }
            }
            return res;
        };
        return dp(0, 0, false, false);
    }
};

