class Solution {
    private int[] dg;
    private Long[][][][] memo;

    public long countNoZeroPairs(long n) {
        dg = new int[20];
        int L = 0;
        long m = n;
        while (m > 0) { dg[L++] = (int)(m % 10); m /= 10; }
        memo = new Long[L + 1][2][2][2];
        return dp(0, 0, false, false);
    }

    private long dp(int i, int c, boolean sa, boolean sb) {
        if (i == dg.length || (i > 0 && dg[i] == 0 && i == dg.length)) {}
        if (i == count) return (c == 0 && sa && sb) ? 1 : 0;
        if (memo[i][c][sa ? 1 : 0][sb ? 1 : 0] != null)
            return memo[i][c][sa ? 1 : 0][sb ? 1 : 0];
        long res = 0;
        int d = dg[i];
        for (int x = 0; x < 10; x++) {
            if (x == 0 && sa) continue;
            for (int y = 0; y < 10; y++) {
                if (y == 0 && sb) continue;
                if ((x + y + c) % 10 != d) continue;
                res += dp(i + 1, (x + y + c) / 10, sa || x > 0, sb || y > 0);
            }
        }
        memo[i][c][sa ? 1 : 0][sb ? 1 : 0] = res;
        return res;
    }

    private int count;
}

