var countNoZeroPairs = function(n) {
    const dg = [];
    let m = n;
    while (m > 0) { dg.push(m % 10); m = Math.floor(m / 10); }
    const L = dg.length;
    const memo = new Map();
    const key = (i, c, sa, sb) => i * 8 + c * 4 + (sa ? 2 : 0) + (sb ? 1 : 0);
    function dp(i, c, sa, sb) {
        if (i === L) return (c === 0 && sa && sb) ? 1 : 0;
        const k = key(i, c, sa, sb);
        if (memo.has(k)) return memo.get(k);
        let res = 0;
        const d = dg[i];
        for (let x = 0; x < 10; x++) {
            if (x === 0 && sa) continue;
            for (let y = 0; y < 10; y++) {
                if (y === 0 && sb) continue;
                if ((x + y + c) % 10 !== d) continue;
                res += dp(i + 1, Math.floor((x + y + c) / 10), sa || x > 0, sb || y > 0);
            }
        }
        memo.set(k, res);
        return res;
    }
    return dp(0, 0, false, false);
};
